import bisect


class _NFA:
    def __init__(self):
        self.eps = []
        self.anchors = []
        self.matches = []

    def new_state(self):
        idx = len(self.eps)
        self.eps.append([])
        self.anchors.append([])
        self.matches.append([])
        return idx

    def add_eps(self, s, t):
        self.eps[s].append(t)

    def add_anchor(self, s, t, typ):
        self.anchors[s].append((t, typ))

    def add_match(self, s, t, pred):
        self.matches[s].append((t, pred))


def _merge_intervals(intervals):
    if not intervals:
        return ()
    intervals.sort()
    merged = []
    for lo, hi in intervals:
        if merged and lo <= merged[-1][1] + 1:
            old_lo, old_hi = merged[-1]
            merged[-1] = (old_lo, max(old_hi, hi))
        else:
            merged.append((lo, hi))
    return tuple(merged)


def _make_class_matcher(neg, intervals):
    if neg:
        if not intervals:
            return lambda ch: True

        def match(ch):
            o = ord(ch)
            idx = bisect.bisect_right(intervals, (o, o)) - 1
            return idx < 0 or intervals[idx][1] < o

        return match

    if not intervals:
        return lambda ch: False

    def match(ch):
        o = ord(ch)
        idx = bisect.bisect_right(intervals, (o, o)) - 1
        return idx >= 0 and intervals[idx][1] >= o

    return match


def _build_node(nfa, node):
    if node is None:
        s = nfa.new_state()
        e = nfa.new_state()
        nfa.add_eps(s, e)
        return s, e

    tag = node[0]

    if tag == "lit":
        ch = node[1]
        s = nfa.new_state()
        e = nfa.new_state()
        nfa.add_match(s, e, lambda c, x=ch: c == x)
        return s, e

    if tag == "any":
        s = nfa.new_state()
        e = nfa.new_state()
        nfa.add_match(s, e, lambda c: True)
        return s, e

    if tag == "class":
        pred = _make_class_matcher(node[1], node[2])
        s = nfa.new_state()
        e = nfa.new_state()
        nfa.add_match(s, e, pred)
        return s, e

    if tag == "anchor":
        s = nfa.new_state()
        e = nfa.new_state()
        nfa.add_anchor(s, e, node[1])
        return s, e

    if tag == "group":
        s = nfa.new_state()
        e = nfa.new_state()
        cs, ce = _build_node(nfa, node[1])
        nfa.add_eps(s, cs)
        nfa.add_eps(ce, e)
        return s, e

    if tag == "alt":
        s = nfa.new_state()
        e = nfa.new_state()
        for child in node[1]:
            cs, ce = _build_node(nfa, child)
            nfa.add_eps(s, cs)
            nfa.add_eps(ce, e)
        return s, e

    if tag == "seq":
        s = nfa.new_state()
        e = nfa.new_state()
        cur = s
        for child in node[1]:
            cs, ce = _build_node(nfa, child)
            nfa.add_eps(cur, cs)
            cur = ce
        nfa.add_eps(cur, e)
        return s, e

    if tag == "star":
        cs, ce = _build_node(nfa, node[1])
        s = nfa.new_state()
        e = nfa.new_state()
        nfa.add_eps(s, cs)
        nfa.add_eps(s, e)
        nfa.add_eps(ce, cs)
        nfa.add_eps(ce, e)
        return s, e

    if tag == "plus":
        cs, ce = _build_node(nfa, node[1])
        s = nfa.new_state()
        e = nfa.new_state()
        nfa.add_eps(s, cs)
        nfa.add_eps(ce, cs)
        nfa.add_eps(ce, e)
        return s, e

    if tag == "may":
        cs, ce = _build_node(nfa, node[1])
        s = nfa.new_state()
        e = nfa.new_state()
        nfa.add_eps(s, cs)
        nfa.add_eps(s, e)
        nfa.add_eps(ce, e)
        return s, e

    raise ValueError("unknown AST node")


class _Parser:
    def __init__(self, pattern):
        self.p = pattern
        self.n = len(pattern)
        self.i = 0

    def parse(self):
        node = self._parse_alternation()
        if self.i != self.n:
            raise ValueError("unmatched parenthesis")
        return node

    def _peek(self):
        if self.i < self.n:
            return self.p[self.i]
        return None

    def _parse_alternation(self):
        alts = [self._parse_concatenation()]
        while self._peek() == "|":
            self.i += 1
            alts.append(self._parse_concatenation())
        if len(alts) == 1:
            return alts[0]
        return ("alt", alts)

    def _parse_concatenation(self):
        seq = []
        while self.i < self.n and self.p[self.i] not in "|)":
            seq.append(self._parse_quantifiable_element())
        if not seq:
            return None
        return ("seq", seq)

    def _parse_quantifiable_element(self):
        node = self._parse_primary()
        if self.i < self.n and self.p[self.i] in "*+?":
            if node[0] == "anchor":
                raise ValueError("quantifier cannot be applied to an anchor")
            op = self.p[self.i]
            self.i += 1
            if op == "*":
                node = ("star", node)
            elif op == "+":
                node = ("plus", node)
            else:
                node = ("may", node)
        return node

    def _parse_primary(self):
        if self.i >= self.n:
            raise ValueError("unexpected end")

        ch = self.p[self.i]

        if ch == "(":
            self.i += 1
            child = self._parse_alternation()
            if self.i >= self.n or self.p[self.i] != ")":
                raise ValueError("unmatched parenthesis")
            self.i += 1
            return ("group", child)

        if ch == "[":
            return self._parse_class()

        if ch == ".":
            self.i += 1
            return ("any",)

        if ch == "^":
            self.i += 1
            return ("anchor", "^")

        if ch == "$":
            self.i += 1
            return ("anchor", "$")

        if ch == "\\":
            if self.i + 1 >= self.n:
                raise ValueError("trailing backslash")
            self.i += 1
            lit = self.p[self.i]
            self.i += 1
            return ("lit", lit)

        if ch in "*+?":
            raise ValueError("unexpected quantifier")

        self.i += 1
        return ("lit", ch)

    def _class_char(self):
        if self.i >= self.n:
            raise ValueError("unterminated character class")
        if self.p[self.i] == "\\":
            if self.i + 1 >= self.n:
                raise ValueError("bad escape in character class")
            ch = self.p[self.i + 1]
            self.i += 2
            return ch
        ch = self.p[self.i]
        self.i += 1
        return ch

    def _parse_class(self):
        self.i += 1
        neg = False
        if self.i < self.n and self.p[self.i] == "^":
            neg = True
            self.i += 1

        intervals = []
        items = 0

        while True:
            if self.i >= self.n:
                raise ValueError("unterminated character class")

            if self.p[self.i] == "]":
                if items == 0:
                    raise ValueError("empty character class")
                self.i += 1
                return ("class", neg, _merge_intervals(intervals))

            c = self._class_char()

            if c == "-":
                intervals.append((ord(c), ord(c)))
                items += 1
                continue

            if (
                self.i < self.n
                and self.p[self.i] == "-"
                and self.i + 1 < self.n
                and self.p[self.i + 1] != "]"
            ):
                self.i += 1
                d = self._class_char()
                lo = ord(c)
                hi = ord(d)
                if lo > hi:
                    raise ValueError("invalid character range")
                intervals.append((lo, hi))
                items += 1
            else:
                intervals.append((ord(c), ord(c)))
                items += 1


def _epsilon_closure(nfa, states, pos, text_len):
    stack = list(states)
    visited = set(states)

    while stack:
        s = stack.pop()

        for t in nfa.eps[s]:
            if t not in visited:
                visited.add(t)
                stack.append(t)

        for t, typ in nfa.anchors[s]:
            if typ == "^" and pos == 0:
                if t not in visited:
                    visited.add(t)
                    stack.append(t)
            elif typ == "$" and pos == text_len:
                if t not in visited:
                    visited.add(t)
                    stack.append(t)

    return visited


def regex_search(pattern: str, text: str) -> bool:
    parser = _Parser(pattern)
    ast = parser.parse()

    nfa = _NFA()
    start, accept = _build_node(nfa, ast)

    active = set()
    n = len(text)

    for pos in range(n + 1):
        active.add(start)
        active = _epsilon_closure(nfa, active, pos, n)

        if accept in active:
            return True

        if pos == n:
            break

        ch = text[pos]
        nxt = set()

        for s in active:
            for t, pred in nfa.matches[s]:
                if pred(ch):
                    nxt.add(t)

        active = nxt

    return False
